/**
 * URL matching for multi-page tours. A step's `pageUrl` decides which page it
 * belongs to; the player uses this to know whether a step is for the current
 * page and when a tour crosses to another page.
 */
import type { UrlMatch } from '@tours/schema';

/** Compile a glob (`*` within a path segment, `**` across) to an anchored RegExp. */
function globToRegExp(glob: string): RegExp {
  const escaped = glob
    .replace(/[.+^${}()|[\]\\]/g, '\\$&') // escape regex specials (keep * and ?)
    .replace(/\*\*/g, '�') // placeholder for **
    .replace(/\*/g, '[^/]*')
    .replace(/�/g, '.*')
    .replace(/\?/g, '.');
  return new RegExp(`^${escaped}$`);
}

/**
 * True if `url` satisfies the match. `regex` wins when present; otherwise the
 * `glob` is used. A match with neither field matches any page.
 */
export function matchUrl(match: UrlMatch | undefined, url: string): boolean {
  if (!match) return true;
  if (match.regex) {
    try {
      return new RegExp(match.regex).test(url);
    } catch {
      return false;
    }
  }
  if (match.glob) {
    try {
      return globToRegExp(match.glob).test(url);
    } catch {
      return false;
    }
  }
  return true;
}

/**
 * Derive a concrete navigation URL from a page matcher, for auto-advancing a
 * multi-page tour. Strips wildcards from an absolute-URL glob (e.g.
 * `https://x.com/recipes*` → `https://x.com/recipes`). Returns null when no
 * usable URL can be derived (relative glob, regex, or no match) — the caller
 * then waits for the visitor to navigate instead.
 */
export function deriveUrl(match: UrlMatch | undefined): string | null {
  if (!match || !match.glob) return null;
  const base = match.glob.replace(/\*+/g, '');
  if (/^https?:\/\//i.test(base) || base.startsWith('#') || base.startsWith('/')) return base;
  return null;
}
